import React, { useState } from 'react';

const AppleLoginComponent = ({ onAuthSuccess, onAuthError }) => {
  const [isLoading, setIsLoading] = useState(false);

  const handleAppleClick = async () => {
    setIsLoading(true);
    
    try {
      // Initialize Apple Sign In
      if (window.AppleID) {
        const response = await window.AppleID.auth.signIn();
        
        // Extract the identity token from Apple's response
        const { authorization } = response;
        const { id_token, code } = authorization;
        
        // Send the token to your FastAPI backend for verification
        const backendResponse = await fetch('/api/auth/apple', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            identity_token: id_token,
            authorization_code: code,
            user: response.user || null
          }),
        });

        if (backendResponse.ok) {
          const { access_token, user_info } = await backendResponse.json();
          onAuthSuccess({ token: access_token, user: user_info });
        } else {
          const errorData = await backendResponse.json();
          throw new Error(errorData.detail || 'Backend authentication failed');
        }
      } else {
        throw new Error('Apple Sign In SDK not loaded');
      }
    } catch (error) {
      console.error('Apple Sign In error:', error);
      onAuthError(error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <button
      onClick={handleAppleClick}
      disabled={isLoading}
      className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 disabled:opacity-50 transition-colors"
    >
      <svg className="w-5 h-5 mr-2" viewBox="0 0 24 24" fill="currentColor">
        <path d="M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701"/>
      </svg>
      {isLoading ? 'Authenticating...' : 'Continue with Apple'}
    </button>
  );
};

export default AppleLoginComponent;